static void ck(VkResult r,const char*what){if(r!=VK_SUCCESS){std::cerr<<what<<" failed: "<<r<<"\n";std::exit(2);}}
static bool load(const std::string&p,std::vector<uint8_t>&v){std::ifstream f(p,std::ios::binary);if(!f)return false;v.assign(std::istreambuf_iterator<char>(f),{});return f.good()||f.eof();}
static uint32_t le24(const uint8_t*p){return p[0]|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16);}
static Astc readAstc(const std::string&p){std::vector<uint8_t>b;if(!load(p,b)||b.size()<16)throw std::runtime_error("cannot read ASTC: "+p);if(b[0]!=0x13||b[1]!=0xAB||b[2]!=0xA1||b[3]!=0x5C)throw std::runtime_error("invalid ASTC magic");Astc a;a.bx=b[4];a.by=b[5];if(b[6]!=1||a.bx!=8||a.by!=8)throw std::runtime_error("requires 2D ASTC 8x8");a.w=le24(&b[7]);a.h=le24(&b[10]);if(!a.w||!a.h||le24(&b[13])!=1)throw std::runtime_error("invalid ASTC dimensions");size_t n=size_t((a.w+7)/8)*((a.h+7)/8)*16;if(b.size()!=16+n)throw std::runtime_error("ASTC size mismatch");a.data.assign(b.begin()+16,b.end());return a;}
static uint32_t memType(Device&d,uint32_t bits,VkMemoryPropertyFlags want,VkMemoryPropertyFlags*actual=nullptr){for(uint32_t i=0;i<d.mem.memoryTypeCount;i++)if((bits&(1u<<i))&&(d.mem.memoryTypes[i].propertyFlags&want)==want){if(actual)*actual=d.mem.memoryTypes[i].propertyFlags;return i;}throw std::runtime_error("no matching Vulkan memory type");}
static Buffer makeVmaBuffer(Device&d,VkDeviceSize size,VkBufferUsageFlags usage,VmaAllocationCreateFlags access){Buffer b;b.size=size;VkBufferCreateInfo bi{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};bi.size=size;bi.usage=usage;bi.sharingMode=VK_SHARING_MODE_EXCLUSIVE;VmaAllocationCreateInfo ai{};ai.usage=VMA_MEMORY_USAGE_AUTO;ai.flags=access;ck(vmaCreateBuffer(d.allocator,&bi,&ai,&b.buffer,&b.allocation,nullptr),"create VMA buffer");VmaAllocationInfo info{};vmaGetAllocationInfo(d.allocator,b.allocation,&info);b.memoryType=info.memoryType;b.heapIndex=d.mem.memoryTypes[info.memoryType].heapIndex;vmaGetAllocationMemoryProperties(d.allocator,b.allocation,&b.properties);ck(vmaMapMemory(d.allocator,b.allocation,&b.mapped),"map VMA buffer");return b;}
static Image makeImage(Device&d,uint32_t w,uint32_t h,VkFormat fmt,VkImageUsageFlags usage){Image x;x.w=w;x.h=h;x.format=fmt;VkImageCreateInfo ci{VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO};ci.imageType=VK_IMAGE_TYPE_2D;ci.format=fmt;ci.extent={w,h,1};ci.mipLevels=1;ci.arrayLayers=1;ci.samples=VK_SAMPLE_COUNT_1_BIT;ci.tiling=VK_IMAGE_TILING_OPTIMAL;ci.usage=usage;ci.sharingMode=VK_SHARING_MODE_EXCLUSIVE;ci.initialLayout=VK_IMAGE_LAYOUT_UNDEFINED;ck(vkCreateImage(d.device,&ci,nullptr,&x.image),"create image");VkMemoryRequirements mr;vkGetImageMemoryRequirements(d.device,x.image,&mr);VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=mr.size;ai.memoryTypeIndex=memType(d,mr.memoryTypeBits,VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);ck(vkAllocateMemory(d.device,&ai,nullptr,&x.memory),"allocate image");ck(vkBindImageMemory(d.device,x.image,x.memory,0),"bind image");VkImageViewCreateInfo vi{VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};vi.image=x.image;vi.viewType=VK_IMAGE_VIEW_TYPE_2D;vi.format=fmt;vi.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};ck(vkCreateImageView(d.device,&vi,nullptr,&x.view),"create image view");return x;}
static void barrier(VkCommandBuffer c,Image&x,VkImageLayout to,VkAccessFlags dst,VkPipelineStageFlags srcStage,VkPipelineStageFlags dstStage){VkImageMemoryBarrier b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER};b.oldLayout=x.layout;b.newLayout=to;b.srcAccessMask=x.layout==VK_IMAGE_LAYOUT_UNDEFINED?0:(x.layout==VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL?VK_ACCESS_SHADER_READ_BIT:x.layout==VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL?VK_ACCESS_TRANSFER_WRITE_BIT:x.layout==VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL?VK_ACCESS_TRANSFER_READ_BIT:VK_ACCESS_SHADER_WRITE_BIT);b.dstAccessMask=dst;b.srcQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED;b.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED;b.image=x.image;b.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};vkCmdPipelineBarrier(c,srcStage,dstStage,0,0,nullptr,0,nullptr,1,&b);x.layout=to;}
static Device init(){Device d;VkApplicationInfo app{VK_STRUCTURE_TYPE_APPLICATION_INFO};app.pApplicationName="astc-vma-staging";app.apiVersion=VK_API_VERSION_1_1;VkInstanceCreateInfo ici{VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO};ici.pApplicationInfo=&app;ck(vkCreateInstance(&ici,nullptr,&d.instance),"create instance");uint32_t n=0;ck(vkEnumeratePhysicalDevices(d.instance,&n,nullptr),"enumerate devices");std::vector<VkPhysicalDevice>ps(n);ck(vkEnumeratePhysicalDevices(d.instance,&n,ps.data()),"enumerate devices");for(auto p:ps){VkPhysicalDeviceProperties pr;vkGetPhysicalDeviceProperties(p,&pr);VkPhysicalDeviceFeatures ft;vkGetPhysicalDeviceFeatures(p,&ft);uint32_t qn=0;vkGetPhysicalDeviceQueueFamilyProperties(p,&qn,nullptr);std::vector<VkQueueFamilyProperties>qs(qn);vkGetPhysicalDeviceQueueFamilyProperties(p,&qn,qs.data());for(uint32_t i=0;i<qn;i++)if((qs[i].queueFlags&VK_QUEUE_COMPUTE_BIT)&&ft.textureCompressionASTC_LDR){VkFormatProperties fp;vkGetPhysicalDeviceFormatProperties(p,VK_FORMAT_ASTC_8x8_UNORM_BLOCK,&fp);if(!(fp.optimalTilingFeatures&VK_FORMAT_FEATURE_SAMPLED_IMAGE_BIT))continue;d.physical=p;d.family=i;d.props=pr;d.timestampBits=qs[i].timestampValidBits;break;}if(d.physical)break;}if(!d.physical||!d.timestampBits)throw std::runtime_error("no Vulkan ASTC/compute device with timestamps");vkGetPhysicalDeviceMemoryProperties(d.physical,&d.mem);float priority=1;VkDeviceQueueCreateInfo qi{VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO};qi.queueFamilyIndex=d.family;qi.queueCount=1;qi.pQueuePriorities=&priority;VkPhysicalDeviceFeatures features{};features.textureCompressionASTC_LDR=VK_TRUE;VkDeviceCreateInfo di{VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO};di.queueCreateInfoCount=1;di.pQueueCreateInfos=&qi;di.pEnabledFeatures=&features;ck(vkCreateDevice(d.physical,&di,nullptr,&d.device),"create device");vkGetDeviceQueue(d.device,d.family,0,&d.queue);VmaAllocatorCreateInfo vci{};vci.instance=d.instance;vci.physicalDevice=d.physical;vci.device=d.device;vci.vulkanApiVersion=VK_API_VERSION_1_1;ck(vmaCreateAllocator(&vci,&d.allocator),"create VMA allocator");VkCommandPoolCreateInfo pci{VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};pci.queueFamilyIndex=d.family;pci.flags=VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;ck(vkCreateCommandPool(d.device,&pci,nullptr,&d.pool),"command pool");VkCommandBuffer cmds[2]{};VkCommandBufferAllocateInfo cai{VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};cai.commandPool=d.pool;cai.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY;cai.commandBufferCount=2;ck(vkAllocateCommandBuffers(d.device,&cai,cmds),"command buffers");d.uploadCmd=cmds[0];d.renderCmd=cmds[1];VkFenceCreateInfo fci{VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};ck(vkCreateFence(d.device,&fci,nullptr,&d.fence),"fence");VkQueryPoolCreateInfo qci{VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO};qci.queryType=VK_QUERY_TYPE_TIMESTAMP;qci.queryCount=3;ck(vkCreateQueryPool(d.device,&qci,nullptr,&d.queries),"timestamps");VkDescriptorSetLayoutBinding bs[2]={{0,VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER,1,VK_SHADER_STAGE_COMPUTE_BIT,nullptr},{1,VK_DESCRIPTOR_TYPE_STORAGE_IMAGE,1,VK_SHADER_STAGE_COMPUTE_BIT,nullptr}};VkDescriptorSetLayoutCreateInfo si{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};si.bindingCount=2;si.pBindings=bs;ck(vkCreateDescriptorSetLayout(d.device,&si,nullptr,&d.dsl),"descriptor layout");VkPipelineLayoutCreateInfo li{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};li.setLayoutCount=1;li.pSetLayouts=&d.dsl;ck(vkCreatePipelineLayout(d.device,&li,nullptr,&d.pl),"pipeline layout");VkShaderModuleCreateInfo smi{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};smi.codeSize=sizeof(sample_spv);smi.pCode=sample_spv;VkShaderModule sm;ck(vkCreateShaderModule(d.device,&smi,nullptr,&sm),"shader module");VkPipelineShaderStageCreateInfo ss{VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO};ss.stage=VK_SHADER_STAGE_COMPUTE_BIT;ss.module=sm;ss.pName="main";VkComputePipelineCreateInfo pi{VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO};pi.stage=ss;pi.layout=d.pl;ck(vkCreateComputePipelines(d.device,VK_NULL_HANDLE,1,&pi,nullptr,&d.pipeline),"compute pipeline");vkDestroyShaderModule(d.device,sm,nullptr);VkDescriptorPoolSize psz[2]={{VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER,1},{VK_DESCRIPTOR_TYPE_STORAGE_IMAGE,1}};VkDescriptorPoolCreateInfo dpi{VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO};dpi.maxSets=1;dpi.poolSizeCount=2;dpi.pPoolSizes=psz;ck(vkCreateDescriptorPool(d.device,&dpi,nullptr,&d.dp),"descriptor pool");return d;}
static VkDescriptorSet makeSet(Device&d,Image&src,Image&dst,VkSampler sampler){VkDescriptorSetAllocateInfo ai{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};ai.descriptorPool=d.dp;ai.descriptorSetCount=1;ai.pSetLayouts=&d.dsl;VkDescriptorSet set;ck(vkAllocateDescriptorSets(d.device,&ai,&set),"descriptor set");VkDescriptorImageInfo a{sampler,src.view,VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL},b{VK_NULL_HANDLE,dst.view,VK_IMAGE_LAYOUT_GENERAL};VkWriteDescriptorSet w[2]{};w[0]={VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};w[0].dstSet=set;w[0].dstBinding=0;w[0].descriptorCount=1;w[0].descriptorType=VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;w[0].pImageInfo=&a;w[1]={VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};w[1].dstSet=set;w[1].dstBinding=1;w[1].descriptorCount=1;w[1].descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;w[1].pImageInfo=&b;vkUpdateDescriptorSets(d.device,2,w,0,nullptr);return set;}
static const char* propsText(VkMemoryPropertyFlags p){static char out[128];out[0]=0;auto add=[&](VkMemoryPropertyFlags f,const char*n){if(p&f){if(out[0])std::strcat(out,"|");std::strcat(out,n);}};add(VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,"DEVICE_LOCAL");add(VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT,"HOST_VISIBLE");add(VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,"HOST_COHERENT");add(VK_MEMORY_PROPERTY_HOST_CACHED_BIT,"HOST_CACHED");add(VK_MEMORY_PROPERTY_LAZILY_ALLOCATED_BIT,"LAZY");return out;}
static bool decode(const std::vector<uint8_t>&payload,const char*codec,uint8_t*out,size_t n){if(std::strcmp(codec,"lz4")==0)return LZ4_decompress_safe((const char*)payload.data(),(char*)out,int(payload.size()),int(n))==int(n);if(std::strcmp(codec,"zstd")==0){auto frame=ZSTD_findFrameCompressedSize(payload.data(),payload.size());if(ZSTD_isError(frame)||frame!=payload.size()||ZSTD_getFrameContentSize(payload.data(),payload.size())!=n)return false;auto got=ZSTD_decompress(out,n,payload.data(),payload.size());return !ZSTD_isError(got)&&got==n;}return false;}
struct Stats{std::vector<double>dec_copy,flush,upload,sample,total,wall;};
static double pct(std::vector<double>v,double p){std::sort(v.begin(),v.end());return v[std::min(v.size()-1,size_t(p*(v.size()-1)))];}
static void run(Device&d,Image&src,Image&dst,Buffer&stage,const std::vector<uint8_t>&raw,const std::vector<uint8_t>&payload,const char*codec,const char*policy,VkDescriptorSet set,Stats&st){std::vector<uint8_t>scratch(raw.size());bool direct=std::strcmp(policy,"current")==0?false:true;for(uint32_t it=0;it<WARM+RUNS;it++){auto wall0=std::chrono::steady_clock::now();auto t0=wall0;if(direct){if(!decode(payload,codec,(uint8_t*)stage.mapped,raw.size()))throw std::runtime_error("direct decode failed");}else{if(!decode(payload,codec,scratch.data(),raw.size()))throw std::runtime_error("scratch decode failed");std::memcpy(stage.mapped,scratch.data(),raw.size());}auto t1=std::chrono::steady_clock::now();if(it==0&&std::memcmp(stage.mapped,raw.data(),raw.size()))throw std::runtime_error("decoded payload differs from ASTC blocks");ck(vmaFlushAllocation(d.allocator,stage.allocation,0,raw.size()),"flush upload allocation");auto t2=std::chrono::steady_clock::now();ck(vkResetFences(d.device,1,&d.fence),"reset render fence");ck(vkResetCommandBuffer(d.uploadCmd,0),"reset upload command");ck(vkResetCommandBuffer(d.renderCmd,0),"reset render command");VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};bi.flags=VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;ck(vkBeginCommandBuffer(d.uploadCmd,&bi),"begin upload");vkCmdResetQueryPool(d.uploadCmd,d.queries,0,3);vkCmdWriteTimestamp(d.uploadCmd,VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,d.queries,0);barrier(d.uploadCmd,src,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,VK_ACCESS_TRANSFER_WRITE_BIT,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT);VkBufferImageCopy cp{};cp.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};cp.imageExtent={src.w,src.h,1};vkCmdCopyBufferToImage(d.uploadCmd,stage.buffer,src.image,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,1,&cp);barrier(d.uploadCmd,src,VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,VK_ACCESS_SHADER_READ_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT);vkCmdWriteTimestamp(d.uploadCmd,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,d.queries,1);ck(vkEndCommandBuffer(d.uploadCmd),"end upload");VkSubmitInfo a{VK_STRUCTURE_TYPE_SUBMIT_INFO};a.commandBufferCount=1;a.pCommandBuffers=&d.uploadCmd;ck(vkQueueSubmit(d.queue,1,&a,VK_NULL_HANDLE),"submit upload");ck(vkBeginCommandBuffer(d.renderCmd,&bi),"begin sample");barrier(d.renderCmd,dst,VK_IMAGE_LAYOUT_GENERAL,VK_ACCESS_SHADER_WRITE_BIT,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT);vkCmdBindPipeline(d.renderCmd,VK_PIPELINE_BIND_POINT_COMPUTE,d.pipeline);vkCmdBindDescriptorSets(d.renderCmd,VK_PIPELINE_BIND_POINT_COMPUTE,d.pl,0,1,&set,0,nullptr);vkCmdDispatch(d.renderCmd,(dst.w+15)/16,(dst.h+15)/16,1);vkCmdWriteTimestamp(d.renderCmd,VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT,d.queries,2);ck(vkEndCommandBuffer(d.renderCmd),"end sample");VkSubmitInfo b{VK_STRUCTURE_TYPE_SUBMIT_INFO};b.commandBufferCount=1;b.pCommandBuffers=&d.renderCmd;ck(vkQueueSubmit(d.queue,1,&b,d.fence),"submit sample");ck(vkWaitForFences(d.device,1,&d.fence,VK_TRUE,UINT64_MAX),"wait render fence");uint64_t q[3];ck(vkGetQueryPoolResults(d.device,d.queries,0,3,sizeof(q),q,sizeof(uint64_t),VK_QUERY_RESULT_64_BIT|VK_QUERY_RESULT_WAIT_BIT),"timestamps");auto wall1=std::chrono::steady_clock::now();double period=d.props.limits.timestampPeriod/1000.0;auto delta=[&](uint64_t x,uint64_t y){uint64_t ticks=y-x;if(d.timestampBits<64)ticks&=((uint64_t(1)<<d.timestampBits)-1);return ticks*period;};if(it>=WARM){st.dec_copy.push_back(std::chrono::duration<double,std::micro>(t1-t0).count());st.flush.push_back(std::chrono::duration<double,std::micro>(t2-t1).count());st.upload.push_back(delta(q[0],q[1]));st.sample.push_back(delta(q[1],q[2]));st.total.push_back(delta(q[0],q[2]));st.wall.push_back(std::chrono::duration<double,std::micro>(wall1-wall0).count());}}}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage: astc-pico lz4|zstd current|cached");const char*codec=argv[1],*policy=argv[2];if((strcmp(codec,"lz4")&&strcmp(codec,"zstd"))||(strcmp(policy,"current")&&strcmp(policy,"current-direct")&&strcmp(policy,"cached")))throw std::runtime_error("unsupported codec/policy");Astc a=readAstc(std::string(DIR)+"/input.astc");std::vector<uint8_t>payload,reference;if(!load(std::string(DIR)+"/input.payload",payload)||!load(std::string(DIR)+"/reference.rgba",reference))throw std::runtime_error("missing payload/reference");if(reference.size()!=size_t(a.w)*a.h*4)throw std::runtime_error("reference dimensions mismatch");Device d=init();std::cout<<"device="<<d.props.deviceName<<" ASTC="<<a.w<<"x"<<a.h<<" bytes="<<a.data.size()<<" codec="<<codec<<" policy="<<policy<<"\n";VkFormat astcFmt=VK_FORMAT_ASTC_8x8_UNORM_BLOCK;Image src=makeImage(d,a.w,a.h,astcFmt,VK_IMAGE_USAGE_TRANSFER_DST_BIT|VK_IMAGE_USAGE_SAMPLED_BIT),dst=makeImage(d,a.w,a.h,VK_FORMAT_R8G8B8A8_UNORM,VK_IMAGE_USAGE_STORAGE_BIT|VK_IMAGE_USAGE_TRANSFER_SRC_BIT);VkSamplerCreateInfo sci{VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO};sci.magFilter=VK_FILTER_NEAREST;sci.minFilter=VK_FILTER_NEAREST;sci.mipmapMode=VK_SAMPLER_MIPMAP_MODE_NEAREST;sci.addressModeU=sci.addressModeV=sci.addressModeW=VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;sci.maxLod=0;VkSampler sampler;ck(vkCreateSampler(d.device,&sci,nullptr,&sampler),"sampler");VkDescriptorSet set=makeSet(d,src,dst,sampler);Buffer current=makeVmaBuffer(d,a.data.size(),VK_BUFFER_USAGE_TRANSFER_SRC_BIT,VMA_ALLOCATION_CREATE_HOST_ACCESS_SEQUENTIAL_WRITE_BIT);Buffer cached=makeVmaBuffer(d,a.data.size(),VK_BUFFER_USAGE_TRANSFER_SRC_BIT,VMA_ALLOCATION_CREATE_HOST_ACCESS_RANDOM_BIT);Buffer&stage=strcmp(policy,"cached")==0?cached:current;if(strcmp(policy,"cached")==0&&!(stage.properties&VK_MEMORY_PROPERTY_HOST_CACHED_BIT))throw std::runtime_error("candidate VMA random allocation did not select HOST_CACHED; direct-write run skipped");Buffer readback=makeVmaBuffer(d,reference.size(),VK_BUFFER_USAGE_TRANSFER_DST_BIT,VMA_ALLOCATION_CREATE_HOST_ACCESS_RANDOM_BIT);std::cout<<"current VMA flags="<<propsText(current.properties)<<" memoryType="<<current.memoryType<<" heap="<<current.heapIndex<<"\n";std::cout<<"cached-candidate VMA flags="<<propsText(cached.properties)<<" memoryType="<<cached.memoryType<<" heap="<<cached.heapIndex<<"\n";std::cout<<"readback VMA flags="<<propsText(readback.properties)<<" memoryType="<<readback.memoryType<<" heap="<<readback.heapIndex<<"\n";Stats st;run(d,src,dst,stage,a.data,payload,codec,policy,set,st);VkBufferImageCopy cp{};cp.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};cp.imageExtent={a.w,a.h,1};ck(vkResetCommandBuffer(d.renderCmd,0),"reset readback command");ck(vkResetFences(d.device,1,&d.fence),"reset readback fence");VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};ck(vkBeginCommandBuffer(d.renderCmd,&bi),"begin readback");barrier(d.renderCmd,dst,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,VK_ACCESS_TRANSFER_READ_BIT,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT);vkCmdCopyImageToBuffer(d.renderCmd,dst.image,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,readback.buffer,1,&cp);VkBufferMemoryBarrier host{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER};host.srcAccessMask=VK_ACCESS_TRANSFER_WRITE_BIT;host.dstAccessMask=VK_ACCESS_HOST_READ_BIT;host.srcQueueFamilyIndex=host.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED;host.buffer=readback.buffer;host.size=VK_WHOLE_SIZE;vkCmdPipelineBarrier(d.renderCmd,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_HOST_BIT,0,0,nullptr,1,&host,0,nullptr);ck(vkEndCommandBuffer(d.renderCmd),"end readback");VkSubmitInfo submit{VK_STRUCTURE_TYPE_SUBMIT_INFO};submit.commandBufferCount=1;submit.pCommandBuffers=&d.renderCmd;ck(vkQueueSubmit(d.queue,1,&submit,d.fence),"submit readback");ck(vkWaitForFences(d.device,1,&d.fence,VK_TRUE,UINT64_MAX),"wait readback");ck(vmaInvalidateAllocation(d.allocator,readback.allocation,0,reference.size()),"invalidate readback");uint32_t maxDelta=0;uint64_t changed=0;for(size_t k=0;k<reference.size();k++){uint32_t dlt=uint32_t(std::abs(int(((uint8_t*)readback.mapped)[k])-int(reference[k])));maxDelta=std::max(maxDelta,dlt);changed+=dlt!=0;}if(maxDelta>2)throw std::runtime_error("GPU sample differs from external ASTC reference by >2 channel values");std::cout<<"external_reference_max_channel_delta="<<maxDelta<<" differing_channels="<<changed<<"\n";std::ofstream out(std::string(DIR)+"/output.rgba",std::ios::binary);out.write((const char*)readback.mapped,reference.size());std::ofstream result(std::string(DIR)+"/result.txt");auto report=[&](std::ostream&o){o<<"device="<<d.props.deviceName<<" extent="<<a.w<<"x"<<a.h<<" codec="<<codec<<" policy="<<policy<<" n="<<st.total.size()<<"\n";o<<"current memoryType="<<current.memoryType<<" properties="<<propsText(current.properties)<<"\ncandidate memoryType="<<cached.memoryType<<" properties="<<propsText(cached.properties)<<"\n";o<<"decode_copy_us_median="<<pct(st.dec_copy,.5)<<" p95="<<pct(st.dec_copy,.95)<<" flush_us_median="<<pct(st.flush,.5)<<" p95="<<pct(st.flush,.95)<<" gpu_upload_us_median="<<pct(st.upload,.5)<<" gpu_sample_us_median="<<pct(st.sample,.5)<<" gpu_total_us_median="<<pct(st.total,.5)<<" wall_us_median="<<pct(st.wall,.5)<<" p95="<<pct(st.wall,.95)<<"\n";};report(std::cout);report(result);std::ofstream csv(std::string(DIR)+"/samples.csv");csv<<"sample,decode_copy_us,flush_us,gpu_upload_us,gpu_sample_us,gpu_total_us,wall_us\n";for(size_t i=0;i<st.total.size();i++)csv<<i<<','<<st.dec_copy[i]<<','<<st.flush[i]<<','<<st.upload[i]<<','<<st.sample[i]<<','<<st.total[i]<<','<<st.wall[i]<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 2;}}
